// Função para descomprimir um vetor de bytes comprimido usando zlib
std::vector-unsigned char> decompressData(const std::vector-unsigned char>& compressedData)
{
    int ret = zlibDecompress2(compressedData.data(), (int)(compressedData.size()), nullptr, Z_BEST_DEFLATION);
    if (ret != Z_OK)
