        std::vector-unsigned char> compressedData = compressData(inputData);
        if (compressedData.empty())
        {
            return 1;
        }

        // 3. Escrever dados comprimidos e cabeçalho
        std::ofstream outFile(outputFilename, std::ios::binary | std::ios::trunc);
        if (!outFile.is_open())
        {
            throw std::runtime_error("Erro ao criar o arquivo de saída.");
        }

        writeHeader(outFile, originalSize, version, type);
