#include <iostream>
#include <fstream>
#include <vector>
#include <zlib.h>
#include <string>

// Assumindo que você tem as funções compressBlock e writeBlockHeader da versão anterior

int main(int argc, char* argv[])
{
    std::string inputFilename = "compressed.bin";
    std::string outputFilename = "decompressed.bin";
    size_t blockSize = 4096;

    try
    {
        std::ifstream inFile(inputFilename, std::ios::binary);
        if (!inFile.is_open())
        {
            throw std::runtime_error("Não foi possível abrir o arquivo de entrada para descompressão.");
        }

        std::ofstream outFile(outputFilename, std::ios::binary | std::ios::trunc);
        if (!outFile.is_open())
        {
            throw std::runtime_error("Não foi possível criar o arquivo de saída para descompressão.");
        }

        while (true)
        {
            // Leia o cabeçalho
            FileHeader header;
            inFile.read(reinterpret_cast-char*>(&header), sizeof(FileHeader));
            if (inFile.gcount() != sizeof(FileHeader))
            {
                break; // Fim do arquivo
            }

            // Verifique se o cabeçalho é válido (por exemplo, tamanho >= 0)
            if (header.size == 0 || header.size > blockSize)
            {
                break;
            }

            // Descomprimir o bloco
            std::vector-unsigned char> compressedBlock(header.size);
            inFile.read(reinterpret_cast-char*>(compressedBlock.data()), header.size);
            if (inFile.gcount() != header.size)
            {
                break;
            }

            std::vector-unsigned char> decompressedBlock = decompressData(compressedBlock);
            if (decompressedBlock.empty())
            {
                throw std::runtime_error("Falha ao descomprimir o bloco.");
            }

            // Escreva o bloco descompactado para a saída
            outFile.write(reinterpret_cast-char*>(decompressedBlock.data()), decompressedBlock.size());
        }

        inFile.close();
        outFile.close();
        std::cout << "Dados descompactados gravados para: " << outputFilename << std::endl;

    }
    catch (const std::exception& e)
    {
        std::cerr << "Ocorreu um erro: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
