    {
        std::ifstream inFile(inputFilename, std::ios::binary);
        if (!inFile.is_open())
        {
            throw std::runtime_error("Não foi possível abrir o arquivo de entrada para descompressão.");
        }

        std::ofstream outFile(outputFilename, std::ios::binary | std::ios::trunc);
        if (!outFile.is_open())
