            }

            // Verifique se o cabeçalho é válido (por exemplo, tamanho >= 0)
            if (header.size == 0 || header.size > blockSize)
            {
                break;
            }

            // Descomprimir o bloco
            std::vector-unsigned char> compressedBlock(header.size);
            inFile.read(reinterpret_cast-char*>(compressedBlock.data()), header.size);
            if (inFile.gcount() != header.size)
            {
                break;
            }

            std::vector-unsigned char> decompressedBlock = decompressData(compressedBlock);
            if (decompressedBlock.empty())
            {
                throw std::runtime_error("Falha ao descomprimir o bloco.");
            }

            // Escreva o bloco descompactado para a saída
            outFile.write(reinterpret_cast-char*>(decompressedBlock.data()), decompressedBlock.size());
        }

        inFile.close();
        outFile.close();
        std::cout << "Dados descompactados gravados para: " << outputFilename << std::endl;

    }
    catch (const std::exception& e)
