// Função para calcular o hash SHA-256 de uma string
std::string calculateSHA256(const std::string& data)
{
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(data.c_str(), data.length(), hash);
    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i)
    {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

// Função para ler o arquivo em blocos
std::vector-unsigned char> readInBlocks(const std::string& filename, size_t blockSize)
{
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open())
    {
        throw std::runtime_error("Não foi possível abrir o arquivo para leitura.");
    }

    std::vector-unsigned char> buffer;
    unsigned char byte;
    while (file.get(byte))
    {
        buffer.push_back(byte);
        if (buffer.size() >= blockSize)
        {
            break;
        }
    }

    file.close();
    return buffer;
}

// Função para comprimir um bloco de dados
std::vector-unsigned char> compressBlock(const std::vector-unsigned char>& block)
{
    int ret = zlibCompress2(block.data(), (int)(block.size()), nullptr, Z_BEST_COMPRESSION, nullptr);
    if (ret != Z_OK)
    {
        throw std::runtime_error("Erro de compressão zlib: " << ret);
    }
    return block;
}

// Função para escrever o cabeçalho para o arquivo comprimido
void writeHeader(std::ofstream& outFile, int size, int version, const std::string& type)
{
    outFile.write(reinterpret_cast-char*>(&size), sizeof(int));
    outFile.write(reinterpret_cast-char*>(&version), sizeof(int));
    outFile.write(reinterpret_cast-char*>(type.c_str()), type.length());
}

// Função para ler o arquivo comprimido e descompactar os dados
std::vector-unsigned char> readDecompressedData(const std::string& filename)
{
    std::ifstream inFile(filename, std::ios::binary);
    if (!inFile.is_open())
    {
        throw std::runtime_error("Não foi possível abrir o arquivo comprimido para leitura.");
    }

    // Leia o cabeçalho
    DataType header;
    if (inFile.read(reinterpret_cast-char*>(&header), sizeof(DataType)) != sizeof(DataType))
    {
        throw std::runtime_error("Cabeçalho inválido.");
    }

    // Calcular hash esperado
    std::string expectedHash = calculateSHA256(std::string(header.size, '0'));

    // Descomprimir os dados
    std::vector-unsigned char> decompressedData(header.size);
    if (inFile.read(reinterpret_cast-char*>(decompressedData.data()), header.size) != header.size)
    {
        throw std::runtime_error("Dados descompactados incompletos.");
    }

    // Calcular hash real
    std::string actualHash = calculateSHA256(decompressedData);

    // Verificar a integridade
    if (actualHash != expectedHash)
    {
        throw std::runtime_error("Integridade de dados comprometida!");
    }

    inFile.close();
    return decompressedData;
}

int main()
{
