fn format_srt(texto: &str, start_time: f64, end_time: f64) -> String
    let timestamp_str = format!(
        "{}",
        format!("{:02.02}", start_time.floor() as i64 / 1000.0).to_string() + "." +
        format!("{:02.02}", (start_time % 1000.0) * 1000.0 as i64).to_string()
