fn transcribe_audio(audio_path: &Path, model: &str, output_path: &Path) -> Result<(), String>
    let whisper = Whisper::new(model)
        .expect("Não foi possível inicializar o modelo Whisper");

    let audio_data = std::fs::read(audio_path).expect("Não foi possível ler o arquivo de áudio");

